parameters.prompt:
=Analise o framework de copywriting do seguinte texto VSL:

TEXTO:
{{ $('Webhook - VSL Input').first().json.vsl_text }}

Frameworks possíveis: PAS (Problem-Agitation-Solution), AIDA (Attention-Interest-Desire-Action), BEFORE-AFTER-BRIDGE, STAR-STORY-SOLUTION, etc.

RETORNE UM JSON EXATO neste formato:
{
  "framework_principal": "nome do framework",
  "confianca_identificacao": 0.0-1.0,
  "estrutura_completa": {
    "introducao": "como inicia",
    "desenvolvimento": "como desenvolve",
    "fechamento": "como fecha"
  },
  "pontos_fortes_estruturais": ["força1", "força2"],
  "pontos_fracos_estruturais": ["fraco1", "fraco2"]
}

object.value:
={{ {
  "length": $('Webhook - VSL Input').first().json.vsl_text.length,
  "word_count": $('Webhook - VSL Input').first().json.vsl_text.split(' ').length,
  "analysis_id": $('Webhook - VSL Input').first().json.analysis_id || $runIndex
} }}

parameters.jsCode:
// Estruturar resposta final no formato Squad Vitascience
const data = $input.first().json;

// Extrair dados das análises
const consciousness = data.consciousness_analysis || {};
const framework = data.framework_analysis || {};
const problems = data.problems_analysis || {};
const improvements = data.improvements_analysis || {};

// Estruturar resposta conforme especificação
const response = {
  // Metadados da análise
  analysis_metadata: {
    id: data.vsl_metadata.analysis_id,
    timestamp: data.timestamp,
    source: data.analysis_source,
    vsl_stats: {
      character_count: data.vsl_metadata.length,
      word_count: data.vsl_metadata.word_count
    }
  },

  // 1. Nível de consciência (1-5) + justificativa
  consciousness_level: {
    level: consciousness.nivel_identificado || 3,
    confidence: Math.round((consciousness.confianca || 0.8) * 100),
    justification: consciousness.justificativa || "Análise baseada em padrões identificados no texto",
    text_indicators: consciousness.indicadores_textuais || [],
    recommended_level: consciousness.nivel_ideal_sugerido || consciousness.nivel_identificado,
    level_explanation: {
      "1": "UNAWARE - Cliente não sabe que tem problema",
      "2": "PROBLEM AWARE - Sabe que tem problema, não sabe soluções", 
      "3": "SOLUTION AWARE - Conhece soluções, não sabe qual escolher",
      "4": "PRODUCT AWARE - Conhece seu produto, não está convencido",
      "5": "MOST AWARE - Pronto para comprar, precisa apenas de incentivo"
    }[consciousness.nivel_identificado] || "Nível não identificado"
  },

  // 2. Framework identificado (PAS, AIDA, etc)
  copywriting_framework: {
    main_framework: framework.framework_principal || "Não identificado",
    confidence: Math.round((framework.confianca_identificacao || 0.7) * 100),
    structure: framework.estrutura_completa || {
      introduction: "Não analisado",
      development: "Não analisado", 
      closing: "Não analisado"
    },
    structural_strengths: framework.pontos_fortes_estruturais || [],
    structural_weaknesses: framework.pontos_fracos_estruturais || []
  },

  // 3. Problemas identificados
  identified_problems: {
    main_problem: problems.problema_principal || "Problema principal não identificado",
    overall_score: problems.score_geral_copy || 5,
    problems_list: (problems.problemas_identificados || []).map((prob, index) => ({
      id: index + 1,
      problem: prob.problema || "Problema não especificado",
      category: prob.categoria || "Geral",
      severity: prob.severidade || 5,
      location: prob.localizacao || "Não especificado",
      why_problem: prob.por_que_problema || "Impacta negativamente a conversão",
      conversion_impact: prob.impacto_conversao || "Redução na taxa de conversão"
    }))
  },

  // 4. Melhorias sugeridas + novos ângulos
  suggested_improvements: {
    quick_wins: improvements.melhorias_quick_wins || [],
    priority_order: improvements.prioridade_implementacao || [],
    new_angles: improvements.novos_angulos_abordagem || [],
    detailed_improvements: (improvements.melhorias_sugeridas || []).map((mel, index) => ({
      id: index + 1,
      improvement: mel.melhoria || "Melhoria não especificada",
      solves_problem: mel.problema_resolvido || "Problema geral",
      eugene_methodology: mel.metodologia_eugene || "Aplicação da metodologia Eugene Schwartz",
      implementation: mel.implementacao || "Implementar conforme metodologia",
      rewritten_example: mel.exemplo_reescrito || "Exemplo não disponível",
      expected_impact: mel.impacto_esperado || "Melhoria na conversão esperada"
    }))
  },

  // 5. Como Eugene consertaria (síntese)
  eugene_fix_summary: {
    main_approach: `Eugene Schwartz consertaria focando no nível de consciência ${consciousness.nivel_identificado || 3} e aplicando o framework ${framework.framework_principal || 'adequado'} de forma mais precisa.`,
    key_changes: [
      "Ajustar linguagem para o nível de consciência correto",
      "Fortalecer a agitação do problema", 
      "Melhorar a apresentação da solução",
      "Intensificar elementos de urgência e escassez",
      "Adicionar mais prova social relevante"
    ],
    expected_result: "Aumento significativo na taxa de conversão através da aplicação precisa da metodologia dos 5 níveis de consciência"
  },

  // Status e qualidade
  analysis_quality: {
    completeness: problems.problemas_identificados?.length >= 3 ? "Alta" : "Média",
    confidence_score: Math.round((
      (consciousness.confianca || 0.8) + 
      (framework.confianca_identificacao || 0.7)
    ) / 2 * 100),
    recommendations_count: improvements.melhorias_sugeridas?.length || 0
  }
};

return { json: response };
